using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.IdentityModel.Tokens;
using MySqlConnector;

var builder = WebApplication.CreateBuilder(args);
var jwt = builder.Configuration.GetSection("Jwt");
var secret = jwt["Key"] ?? "";
if (secret.Length < 32 || secret.StartsWith("REPLACE_")) throw new Exception("Configure a random Jwt:Key of at least 32 characters in appsettings.json");
builder.Services.AddEndpointsApiExplorer(); builder.Services.AddSwaggerGen();
builder.Services.AddCors(o => o.AddDefaultPolicy(p => p.AllowAnyHeader().AllowAnyMethod().SetIsOriginAllowed(_ => true)));
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o => o.TokenValidationParameters = new TokenValidationParameters { ValidateIssuer=true,ValidIssuer=jwt["Issuer"],ValidateAudience=true,ValidAudience=jwt["Audience"],ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secret)),ValidateLifetime=true });
builder.Services.AddAuthorization();
var app=builder.Build(); app.UseCors(); app.UseAuthentication(); app.UseAuthorization(); if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();}
var cs=builder.Configuration.GetConnectionString("Darwin")!; MySqlConnection Db()=>new(cs);
app.MapGet("/health",()=>Results.Ok(new{status="ok",service="DarwinTradingMobileAPI"}));
app.MapPost("/api/auth/login",async(Login x)=>{
 if(string.IsNullOrWhiteSpace(x.Username)||string.IsNullOrEmpty(x.Password))return Results.BadRequest(new{message="Enter username and password."});
 await using var c=Db();await c.OpenAsync();await using var q=new MySqlCommand("SELECT id,username,password_hash,full_name,role,is_active,is_locked,failed_attempts,COALESCE(locked_until>NOW(),0) temp_locked,COALESCE(TIMESTAMPDIFF(MINUTE,NOW(),locked_until),0) mins_left FROM users WHERE username=@u",c);q.Parameters.AddWithValue("@u",x.Username.Trim());await using var r=await q.ExecuteReaderAsync();if(!await r.ReadAsync())return Results.Unauthorized();
 int id=r.GetInt32("id"),active=r.GetInt32("is_active"),locked=r.GetInt32("is_locked"),temp=r.GetInt32("temp_locked"),mins=r.GetInt32("mins_left");string username=r.GetString("username"),hash=r.GetString("password_hash"),full=r.GetString("full_name"),role=r.IsDBNull("role")?"":r.GetString("role");await r.CloseAsync();
 if(active==0||(role.ToLowerInvariant()!="superadmin"&&(locked!=0||temp!=0)))return Results.Json(new{message=temp!=0?$"Account temporarily locked for about {mins+1} minute(s).":"Account disabled or locked."},statusCode:403);
 if(!Verify(x.Password,hash)){if(role.ToLowerInvariant()!="superadmin"){await using var f=new MySqlCommand("UPDATE users SET locked_until=IF(failed_attempts+1>=5,DATE_ADD(NOW(),INTERVAL 15 MINUTE),locked_until),failed_attempts=IF(failed_attempts+1>=5,0,failed_attempts+1) WHERE id=@id",c);f.Parameters.AddWithValue("@id",id);await f.ExecuteNonQueryAsync();}return Results.Unauthorized();}
 await using(var reset=new MySqlCommand("UPDATE users SET failed_attempts=0,locked_until=NULL,last_login=NOW() WHERE id=@id",c)){reset.Parameters.AddWithValue("@id",id);await reset.ExecuteNonQueryAsync();}
 var claims=new[]{new Claim(ClaimTypes.NameIdentifier,id.ToString()),new Claim(ClaimTypes.Name,username),new Claim(ClaimTypes.Role,role),new Claim("full_name",full)};var token=new JwtSecurityToken(jwt["Issuer"],jwt["Audience"],claims,expires:DateTime.UtcNow.AddHours(10),signingCredentials:new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secret)),SecurityAlgorithms.HmacSha256));return Results.Ok(new{token=new JwtSecurityTokenHandler().WriteToken(token),user=new{id,username,fullName=full,role}});
});
app.MapGet("/api/dashboard",async()=>{await using var c=Db();await c.OpenAsync();async Task<long> Count(string sql){await using var q=new MySqlCommand(sql,c);return Convert.ToInt64(await q.ExecuteScalarAsync());}return Results.Ok(new{products=await Count("SELECT COUNT(*) FROM products"),categories=await Count("SELECT COUNT(*) FROM categories"),lowStock=await Count("SELECT COUNT(*) FROM products WHERE qty_on_hand<=low_stock_threshold"),draftDeliveries=await Count("SELECT COUNT(*) FROM deliveries WHERE status='draft'")});}).RequireAuthorization();
app.MapGet("/api/categories",async()=>{await using var c=Db();await c.OpenAsync();await using var q=new MySqlCommand("SELECT id,name,description FROM categories ORDER BY name",c);await using var r=await q.ExecuteReaderAsync();var a=new List<object>();while(await r.ReadAsync())a.Add(new{id=r.GetInt32("id"),name=r.GetString("name"),description=r.IsDBNull("description")?null:r.GetString("description")});return Results.Ok(a);}).RequireAuthorization();
app.MapPost("/api/categories",async(Category x)=>{if(string.IsNullOrWhiteSpace(x.Name))return Results.BadRequest();await using var c=Db();await c.OpenAsync();await using var q=new MySqlCommand("INSERT INTO categories(name,description) VALUES(@n,@d)",c);q.Parameters.AddWithValue("@n",x.Name.Trim());q.Parameters.AddWithValue("@d",(object?)x.Description??DBNull.Value);try{await q.ExecuteNonQueryAsync();return Results.Ok(new{id=q.LastInsertedId});}catch(MySqlException e)when(e.Number==1062){return Results.Conflict(new{message="Category already exists."});}}).RequireAuthorization();
app.MapGet("/api/products",async(string? search)=>{await using var c=Db();await c.OpenAsync();await using var q=new MySqlCommand("SELECT p.id,p.name,p.measurement,p.barcode,p.qty_on_hand,p.cost_price,p.selling_price,p.low_stock_threshold,c.name category FROM products p JOIN categories c ON c.id=p.category_id WHERE (@s IS NULL OR p.name LIKE @like OR p.barcode LIKE @like) ORDER BY p.name LIMIT 500",c);q.Parameters.AddWithValue("@s",(object?)search??DBNull.Value);q.Parameters.AddWithValue("@like",$"%{search}%");await using var r=await q.ExecuteReaderAsync();var a=new List<object>();while(await r.ReadAsync())a.Add(new{id=r.GetInt32("id"),name=r.GetString("name"),measurement=r.GetString("measurement"),barcode=r.GetString("barcode"),stock=r.GetInt32("qty_on_hand"),costPrice=r.GetDecimal("cost_price"),sellingPrice=r.GetDecimal("selling_price"),lowStockThreshold=r.GetInt32("low_stock_threshold"),category=r.GetString("category")});return Results.Ok(a);}).RequireAuthorization();
app.MapGet("/api/suppliers",async()=>{await using var c=Db();await c.OpenAsync();await using var q=new MySqlCommand("SELECT id,name,company_name,company_address,contact_number FROM suppliers ORDER BY company_name",c);await using var r=await q.ExecuteReaderAsync();var a=new List<object>();while(await r.ReadAsync())a.Add(new{id=r.GetInt32("id"),name=r.GetString("name"),companyName=r.GetString("company_name"),address=r.GetString("company_address"),phone=r.IsDBNull("contact_number")?null:r.GetString("contact_number")});return Results.Ok(a);}).RequireAuthorization();
app.MapGet("/api/deliveries",async(string? status)=>{await using var c=Db();await c.OpenAsync();await using var q=new MySqlCommand("SELECT d.id,d.batch_no,d.status,d.delivery_date,d.total_cost,d.expected_profit,s.company_name,(SELECT COUNT(*) FROM delivery_items i WHERE i.delivery_id=d.id) item_count FROM deliveries d JOIN suppliers s ON s.id=d.supplier_id WHERE (@s IS NULL OR d.status=@s) ORDER BY (d.status='draft') DESC,d.id DESC LIMIT 300",c);q.Parameters.AddWithValue("@s",(object?)status??DBNull.Value);await using var r=await q.ExecuteReaderAsync();var a=new List<object>();while(await r.ReadAsync())a.Add(new{id=r.GetInt32("id"),batchNo=r.GetString("batch_no"),status=r.GetString("status"),deliveryDate=r.GetDateTime("delivery_date"),totalCost=r.GetDecimal("total_cost"),expectedProfit=r.GetDecimal("expected_profit"),supplier=r.GetString("company_name"),itemCount=r.GetInt32("item_count")});return Results.Ok(a);}).RequireAuthorization();
app.Run();
static bool Verify(string password,string stored){try{var p=stored.Split('$');if(p.Length!=4||p[0]!="PBKDF2-SHA256")return false;var salt=Convert.FromBase64String(p[2]);var expected=Convert.FromBase64String(p[3]);var actual=Rfc2898DeriveBytes.Pbkdf2(password,salt,int.Parse(p[1]),HashAlgorithmName.SHA256,expected.Length);return CryptographicOperations.FixedTimeEquals(actual,expected);}catch{return false;}}
record Login(string Username,string Password); record Category(string Name,string? Description);
